import { z } from 'zod';
import type { DataCrossCheck } from '../data/game-data';
import type { WorldMap } from './world-map';

/**
 * Each country's real-world starting data for the campaign's first year
 * (F71), `data/country_start.json`. Generated by `npm run
 * import:starting-data` from the IMF and World Bank tables saved in
 * `packages/tools/starting-data/` plus hand-written government types; never
 * edit the output by hand.
 *
 * First pass: population, economy size (GDP) and government type; since F06
 * also the demographics the population model starts from (birth and death
 * rates, labor force, unemployment, armed forces). The
 * numbers are where the campaign STARTS: once population (F06), the economy
 * (F65) and politics change during a campaign, the current values move into
 * `GameState` and these remain only the starting point.
 */
const countryId = z
  .string()
  .regex(/^[A-Z]{3}$/, 'country ids are three capital letters (ISO 3166-1 alpha-3)');
const id = z
  .string()
  .regex(/^[a-z0-9]+(_[a-z0-9]+)*$/, 'ids are lowercase letters, digits and single underscores');
const sourceKey = z.string().regex(/^[a-z][A-Za-z0-9]*$/, 'source keys are camelCase');

/** `data/country_start.json` */
export const countryStartFileSchema = z.strictObject({
  /** The year the numbers describe: the campaign's first year. */
  year: z.int().min(2000).max(2100),
  /** Where the numbers come from, by key (referred to by each country's `populationSource` and `gdpSource`). */
  sources: z.record(
    sourceKey,
    z.strictObject({
      title: z.string().min(1),
      url: z.string().optional(),
      /** Edition and download date, for example "October 2026, downloaded 2026-11-13". */
      edition: z.string().optional(),
    }),
  ),
  countries: z.array(
    z.strictObject({
      id: countryId,
      /** People living in the country, including merged territories (map-config `includes`). */
      population: z.int().positive(),
      /** Gross domestic product, nominal, in millions of US dollars. */
      gdpMillionUsd: z.number().positive(),
      /** An id from `data/government_types.json`. */
      governmentType: id,
      populationSource: sourceKey,
      gdpSource: sourceKey,
      /** Present when the GDP figure is from an earlier year than `year` (no newer one exists). */
      gdpYear: z.int().optional(),
      /** Births and deaths in a year per 1,000 people (F06). */
      birthsPerThousand: z.number().min(0).max(60),
      deathsPerThousand: z.number().min(0).max(40),
      /** The labor force (people who work or look for work) as a share of the population (F06). */
      laborForceShare: z.number().min(0.1).max(0.9),
      /** The share of the labor force without a job (F06). */
      unemploymentRate: z.number().min(0).max(0.6),
      /** The armed forces as a share of the labor force (F06). */
      armedForcesShare: z.number().min(0).max(0.3),
      demographicsSource: sourceKey,
      /** Notes on how the numbers or the government type were chosen (for developers, not shown in the game). */
      notes: z.array(z.string().min(1)).optional(),
    }),
  ),
});

export type CountryStartFile = z.infer<typeof countryStartFileSchema>;
export type CountryStartData = CountryStartFile['countries'][number];

/**
 * GDP per person outside this range (US$) is almost certainly a mistake (a
 * figure in the wrong unit, or a territory added twice). The real range is
 * about 200 (Burundi, South Sudan) to 300,000 (Monaco).
 */
export const GDP_PER_PERSON_RANGE_USD = { min: 100, max: 500_000 } as const;

/**
 * Cross-file checks: exactly one entry for every country in
 * `countries.json`, known government types and sources, the campaign's start
 * year, and plausible GDP per person.
 */
export const checkCountryStart: DataCrossCheck = (data, report) => {
  const file = 'country_start.json';
  const start = data.countryStart;
  const issue = (path: string, message: string) => report({ file, path, message });

  if (start.year !== data.gameConfig.startDate.year) {
    issue(
      'year',
      `the starting data is for ${start.year}, but the campaign starts in ${data.gameConfig.startDate.year} (game_config.json)`,
    );
  }
  const governmentTypes = new Set(data.governmentTypes.governmentTypes.map((g) => g.id));
  const countries = new Set(data.countries.countries.map((c) => c.id));
  const seen = new Map<string, number>();

  start.countries.forEach((c, index) => {
    const at = `countries.${index}`;
    const first = seen.get(c.id);
    if (first !== undefined)
      issue(`${at}.id`, `duplicate country "${c.id}" (also at countries.${first})`);
    else seen.set(c.id, index);
    if (!countries.has(c.id))
      issue(`${at}.id`, `unknown country "${c.id}" (not in countries.json)`);
    if (!governmentTypes.has(c.governmentType))
      issue(
        `${at}.governmentType`,
        `unknown government type "${c.governmentType}" (not in government_types.json)`,
      );
    if (!Object.hasOwn(start.sources, c.populationSource))
      issue(`${at}.populationSource`, `unknown source "${c.populationSource}"`);
    if (!Object.hasOwn(start.sources, c.gdpSource))
      issue(`${at}.gdpSource`, `unknown source "${c.gdpSource}"`);
    if (!Object.hasOwn(start.sources, c.demographicsSource))
      issue(`${at}.demographicsSource`, `unknown source "${c.demographicsSource}"`);
    const perPerson = (c.gdpMillionUsd * 1e6) / c.population;
    if (perPerson < GDP_PER_PERSON_RANGE_USD.min || perPerson > GDP_PER_PERSON_RANGE_USD.max) {
      issue(
        at,
        `GDP per person of ${Math.round(perPerson).toLocaleString('en')} US$ is outside ` +
          `${GDP_PER_PERSON_RANGE_USD.min}–${GDP_PER_PERSON_RANGE_USD.max.toLocaleString('en')} US$: check the units`,
      );
    }
  });
  for (const c of data.countries.countries) {
    if (!seen.has(c.id)) issue('countries', `no starting data for country "${c.id}"`);
  }
};

/**
 * The starting data in the world's country order (index = country index),
 * ready for fast lookups and for sending to the game.
 */
export interface CountryStartTable {
  /** The year the numbers describe. */
  readonly year: number;
  readonly population: Float64Array;
  readonly gdpMillionUsd: Float64Array;
  /** Government type id of each country. */
  readonly governmentType: readonly string[];
  /** Births and deaths in a year per 1,000 people (F06). */
  readonly birthsPerThousand: Float64Array;
  readonly deathsPerThousand: Float64Array;
  /** The labor force as a share of the population (F06). */
  readonly laborForceShare: Float64Array;
  /** The share of the labor force without a job (F06). */
  readonly unemploymentRate: Float64Array;
  /** The armed forces as a share of the labor force (F06). */
  readonly armedForcesShare: Float64Array;
}

export function buildCountryStartTable(
  start: CountryStartFile,
  world: WorldMap,
): CountryStartTable {
  const count = world.countryIds.length;
  const population = new Float64Array(count);
  const gdpMillionUsd = new Float64Array(count);
  const governmentType: string[] = new Array<string>(count).fill('');
  const birthsPerThousand = new Float64Array(count);
  const deathsPerThousand = new Float64Array(count);
  const laborForceShare = new Float64Array(count);
  const unemploymentRate = new Float64Array(count);
  const armedForcesShare = new Float64Array(count);
  for (const c of start.countries) {
    const index = world.countryIndex.get(c.id);
    if (index === undefined) throw new Error(`Country start data: unknown country "${c.id}"`);
    population[index] = c.population;
    gdpMillionUsd[index] = c.gdpMillionUsd;
    governmentType[index] = c.governmentType;
    birthsPerThousand[index] = c.birthsPerThousand;
    deathsPerThousand[index] = c.deathsPerThousand;
    laborForceShare[index] = c.laborForceShare;
    unemploymentRate[index] = c.unemploymentRate;
    armedForcesShare[index] = c.armedForcesShare;
  }
  return {
    year: start.year,
    population,
    gdpMillionUsd,
    governmentType,
    birthsPerThousand,
    deathsPerThousand,
    laborForceShare,
    unemploymentRate,
    armedForcesShare,
  };
}
